    cross: [['....GGGG....', '....GwwG....', '....GwwG....', 'GGGGGwwGGGGG', 'GwwwwwwwwwwG', 'GwwwwwwwwwwG', 'GGGGGwwGGGGG', '....GwwG....', '....GwwG....', '....GGGG....'], { G: '#3f8a4a', w: '#dfffa0' }],
