  for (let y = y0; y <= y1; y++) { const i = y * LW + tx; L.grid[i] = T.AIR; tileSpr[i] = null; destroyed.add(i);
    burst(tx * TS + 8, y * TS + 8, 5, ['#e8e8f0', '#8a8478'], 50, 0.4, 0, 1); }
