  SFX.vigilFull(); SFX.braceSet(); shakeCam(4); zoomKick(1.05, 0.22); rumble(140, 0.6);
  ringAt(P.x, P.y - 10, 26, '#8fd160', 0.4); ringAt(P.x, P.y - 10, 14, '#dff0d8', 0.28);
