  for (let i = 0; i < 5; i++) parts.push({ x, y, vx: (Math.random() - 0.5) * 120, vy: -60 - Math.random() * 90, life: 0.6, max: 0.6, col: Math.random() < 0.6 ? '#ffd34a' : '#fff6c8', size: 2, grav: 400 });
