    for (let i = 0; i < 18; i++) parts.push({ x: P.x + P.face * 12, y: P.y - 12 + (Math.random() - 0.5) * 14, vx: P.face * (80 + Math.random() * 220), vy: (Math.random() - 0.5) * 90, life: 0.4, max: 0.4, col: ['#ff6b2c', '#ff9a5c', '#ffd36b'][(Math.random() * 3) | 0], size: 2, grav: -20 });
