      for (const q of props) if (q.t === 'cargo' && !q.gone && sp0 > 50 && Math.abs(q.x - pr.x) < 16 && Math.abs(q.y - pr.y) < 12) { q.gone = true; q.back = 14; SFX.crack(); burst(q.x, q.y - 6, 12, ['#8a5a32', '#c9b27c', '#5c3a1d'], 90, 0.5); }
