  if (e.riseT >= 0.7) { e.risen = true; e.gone = 0; e.face = Math.sign(P.x - e.x) || e.face; e.stagger = Math.max(e.stagger || 0, 0.25); SFX.foeGasp && SFX.foeGasp('sailor'); }
