      g.fillStyle = '#2a2630'; for (let k = 14; k < len - 10; k += 34) g.fillRect(k, 0, 3, 8);   /* her iron hoops */
      g.fillStyle = '#efe6d2'; g.fillRect(len - 22, -10, 3, 18); g.fillRect(len - 36, 4, 22, 3);   /* a broken yard at the head of her */
      g.restore();
