  const frac = e.hp / e.maxHp, busy = /Tell$/.test(e.mode || '') || ['wake', 'blink', 'change', 'open', 'swallow'].includes(e.mode);
  const R = MG.A || (MG.A = { stage: 1, sub: 0, subHp: 0, runes: [], warned: {} });
