  for (const a of e.arms) if (a.two && !a.severed && a.hp > 0) { const hp = a.hp; a.st = 'idle'; a.hp = hp; a.low = false; a.tx = a.bx; a.ty = fl - 20; a.flash = 0; if (a.ae) { a.ae.alive = true; a.ae.hp = hp; a.ae.maxHp = hp; } krakenSplash(a.bx, fl, 14); }
