      if (Math.random() < dt * 16) parts.push({ x: e.x + e.face * 8, y: e.y - 1, vx: -e.face * (30 + Math.random() * 30), vy: -30 - Math.random() * 30, life: 0.3, max: 0.3, col: '#8a6a40', size: 1, grav: 300 });
      if (e.modeT <= 0) { e.mode = 'charge'; e.modeT = 1.1; e.hit = false; SFX.badgerCharge(); }
