      const r = moveBody(e, e.vx * dt, e.vy * dt, false); e.onGround = r.ground; if (r.ground) { e.vy = 0; e.vx *= 0.5; } if (r.hitX) e.vx = -e.vx;
      if (inPool && e.y > surf + 4) { e.mode = 'lurk'; e.cd = 2; e.gone = 1; SFX.splash(); burst(e.x, surf, 6, ['#eefaff', '#bfe6f5'], 50, 0.35); ripples.push({ x: e.x, life: 1 }); }
