  g.globalAlpha = tell ? 0.55 : 0.3; g.fillStyle = '#1e2a1a'; g.fillRect(x - 12, y + 4, 22, 3); g.fillRect(x + f * 10 - (f < 0 ? 6 : 0), y + 5, 6, 1);   /* its shadow under the surface */
  g.globalAlpha = 1; g.fillStyle = '#9aa05a'; const sx = x + f * (tell ? 9 : 11); g.fillRect(f > 0 ? sx : sx - 4, y - (tell ? 1 : 0), 4, 1);   /* the snout tip breaking the water */
