  if (!p2 && e.hp < e.maxHp * 0.5) { e.phase = 2; number(e.x, e.y - 30, 'THE SKY DARKENS', '#c9a0ff'); SFX.callerChant(); shakeCam(3); }
  e.face = Math.sign(d) || e.face;
