      if (!e.hit && !P.dead && ad < 14 && dy < 26) { e.hit = true; const res = damagePlayer(e.x, DMG.assassinLunge, { unblockable: true }); if (res === 'hit') { P.vx = e.face * 150; P.vy = -120; } }
