          if (res === 'blocked') { e.mode = 'reel'; e.modeT = 1.5; e.stagger = 1.5; e.vx = -e.face * 90; number(e.x, e.y - e.h - 12, 'PARRIED', '#8fd160'); SFX.clank(); }
