  burst(pr.x, pr.y, 6, ['#8a919c', '#bfe6f5'], 40, 0.4);
  if (!(PROG.ballastTold > 1)) { PROG.ballastTold = (PROG.ballastTold || 0) + 1; hintT = 5;
    hintMsg = 'CARRY A STONE TO SINK AND WALK THE BOTTOM. JUMP DROPS IT AND YOU RISE. EACH ROOM HAS FEW.'; }
