  g.fillStyle = '#6a5a3c'; for (let x = L0 - ((ox + 7) % 14); x < R0; x += 14) { g.fillRect(x, fl + 10, 6, 1); g.fillRect(x + 4, fl + 16, 4, 1); }
  g.fillStyle = '#5a4c32'; for (let x = L0 - ((ox + 11) % 23); x < R0; x += 23) g.fillRect(x, fl + 23, 9, 1);
